import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';
import AIAssistant from './AIAssistant';

// --- Constants ---
const SNAP_THRESHOLD = 0.2; // Reduced from 0.3 for better precision
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-4; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number; // Current dynamic height during drag
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

const isPointOnSegmentStrict = (p: THREE.Vector3, a: THREE.Vector3, b: THREE.Vector3, tolerance = 0.05) => {
    if (p.distanceTo(a) < tolerance || p.distanceTo(b) < tolerance) return false;
    const distSq = distToSegmentSquared(p, a, b);
    return distSq < (tolerance * tolerance);
};

const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;
    if (u >= 0 && u <= 1 && v >= 0 && v <= 1) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

const splitPolygonByLine = (polyPoints: IPoint[], cutStart: IPoint, cutEnd: IPoint): [IPoint[], IPoint[]] | null => {
    const intersections: { point: IPoint; edgeIndex: number; dist: number }[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];
        const hit = getLineIntersection(p1, p2, cutStart, cutEnd);
        if (hit) {
            const isP1 = Math.abs(hit.x - p1.x) < 0.001 && Math.abs(hit.z - p1.z) < 0.001;
            const isP2 = Math.abs(hit.x - p2.x) < 0.001 && Math.abs(hit.z - p2.z) < 0.001;
            if (!isP1 && !isP2) {
                const dist = Math.sqrt((hit.x - cutStart.x)**2 + (hit.z - cutStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }
    if (intersections.length !== 2) return null;
    intersections.sort((a, b) => a.dist - b.dist);
    const [int1, int2] = intersections;
    const fullCycle: IPoint[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        fullCycle.push(polyPoints[i]);
        if (i === int1.edgeIndex) fullCycle.push(int1.point);
        if (i === int2.edgeIndex) fullCycle.push(int2.point);
    }
    const idx1 = fullCycle.indexOf(int1.point);
    const idx2 = fullCycle.indexOf(int2.point);
    if (idx1 === -1 || idx2 === -1) return null;
    const minIdx = Math.min(idx1, idx2);
    const maxIdx = Math.max(idx1, idx2);
    const polyA = fullCycle.slice(minIdx, maxIdx + 1);
    const polyB = [...fullCycle.slice(maxIdx), ...fullCycle.slice(0, minIdx + 1)];
    return [polyA, polyB];
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge') return null;

    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => {
        if (p.x < minX) minX = p.x;
        if (p.x > maxX) maxX = p.x;
    });

    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];

    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    const angle = -shape.rotation; 

    const dx = Math.cos(angle) * scaledHalfLen;
    const dz = Math.sin(angle) * scaledHalfLen;

    const p1 = new THREE.Vector3(pos.x - dx, pos.y, pos.z - dz);
    const p2 = new THREE.Vector3(pos.x + dx, pos.y, pos.z + dz);

    return [p1, p2];
};

// --- Face Detection & Planar Graph Algorithms ---
const fragmentSegments = (segments: { start: IPoint; end: IPoint }[]): { start: IPoint; end: IPoint }[] => {
    let currentSegments = [...segments];
    let hasIntersections = true;

    while (hasIntersections) {
        hasIntersections = false;
        const newSegments: { start: IPoint; end: IPoint }[] = [];
        const processed = new Set<number>();

        for (let i = 0; i < currentSegments.length; i++) {
            if (processed.has(i)) continue;
            let s1 = currentSegments[i];
            let broken = false;

            for (let j = i + 1; j < currentSegments.length; j++) {
                if (processed.has(j)) continue;
                let s2 = currentSegments[j];

                const intersection = getLineIntersection(s1.start, s1.end, s2.start, s2.end);

                const isEndpoint = (p: IPoint, s: {start: IPoint, end: IPoint}) => 
                    (Math.abs(p.x - s.start.x) < EPSILON && Math.abs(p.z - s.start.z) < EPSILON) ||
                    (Math.abs(p.x - s.end.x) < EPSILON && Math.abs(p.z - s.end.z) < EPSILON);

                if (intersection && !isEndpoint(intersection, s1) && !isEndpoint(intersection, s2)) {
                    newSegments.push({ start: s1.start, end: intersection });
                    newSegments.push({ start: intersection, end: s1.end });
                    newSegments.push({ start: s2.start, end: intersection });
                    newSegments.push({ start: intersection, end: s2.end });
                    processed.add(i);
                    processed.add(j);
                    broken = true;
                    hasIntersections = true;
                    break; 
                }
            }
            if (!broken) {
                newSegments.push(s1);
            }
        }
        if (hasIntersections) {
            currentSegments = newSegments;
        }
    }
    return currentSegments;
};

const findClosedCycles = (segments: { start: IPoint; end: IPoint }[]): IPoint[][] => {
    const nodes: Record<string, { x: number, z: number, neighbors: string[] }> = {};
    const key = (p: IPoint) => `${p.x.toFixed(4)},${p.z.toFixed(4)}`;
    const addNode = (p: IPoint) => {
        const k = key(p);
        if (!nodes[k]) nodes[k] = { x: p.x, z: p.z, neighbors: [] };
        return k;
    };

    segments.forEach(s => {
        if (Math.abs(s.start.x - s.end.x) < EPSILON && Math.abs(s.start.z - s.end.z) < EPSILON) return;
        const k1 = addNode(s.start);
        const k2 = addNode(s.end);
        if (!nodes[k1].neighbors.includes(k2)) nodes[k1].neighbors.push(k2);
        if (!nodes[k2].neighbors.includes(k1)) nodes[k2].neighbors.push(k1);
    });

    const cycles: IPoint[][] = [];
    const visitedEdges = new Set<string>();

    Object.keys(nodes).forEach(uKey => {
        const uNode = nodes[uKey];
        uNode.neighbors.sort((aKey, bKey) => {
            const aNode = nodes[aKey];
            const bNode = nodes[bKey];
            const angA = Math.atan2(aNode.z - uNode.z, aNode.x - uNode.x);
            const angB = Math.atan2(bNode.z - uNode.z, bNode.x - uNode.x);
            return angA - angB;
        });

        uNode.neighbors.forEach(vKey => {
            const edgeKey = `${uKey}->${vKey}`;
            if (visitedEdges.has(edgeKey)) return;

            const path = [uKey];
            const pathSet = new Set([uKey]);
            let curr = vKey;
            let prev = uKey;
            let isCycle = false;

            while (true) {
                visitedEdges.add(`${prev}->${curr}`);
                path.push(curr);

                if (curr === uKey) {
                    isCycle = true;
                    break;
                }

                if (pathSet.has(curr)) break;
                pathSet.add(curr);

                const currNode = nodes[curr];
                const prevNode = nodes[prev];

                const neighbors = currNode.neighbors;
                const prevIdx = neighbors.indexOf(prev);
                const nextIdx = (prevIdx - 1 + neighbors.length) % neighbors.length;
                const nextKey = neighbors[nextIdx];

                if (!nextKey || nextKey === prev) break;

                prev = curr;
                curr = nextKey;
            }

            if (isCycle && path.length > 2) {
                const points = path.map(k => ({ x: nodes[k].x, y: 0, z: nodes[k].z }));
                let area = 0;
                for(let i=0; i<points.length; i++) {
                    const p1 = points[i];
                    const p2 = points[(i+1)%points.length];
                    area += (p2.x - p1.x) * (p2.z + p1.z);
                }
                if (Math.abs(area) > 0.01) {
                    cycles.push(points);
                }
            }
        });
    });

    const uniqueCycles: IPoint[][] = [];
    const cycleFingerprints = new Set<string>();

    cycles.forEach(cycle => {
        const center = { x: 0, z: 0 };
        cycle.forEach(p => { center.x += p.x; center.z += p.z });
        center.x /= cycle.length;
        center.z /= cycle.length;
        const fingerprint = `${center.x.toFixed(3)},${center.z.toFixed(3)}_${cycle.length}`;
        if (!cycleFingerprints.has(fingerprint)) {
            cycleFingerprints.add(fingerprint);
            uniqueCycles.push(cycle);
        }
    });

    return uniqueCycles;
};


const getBoundingCenter = (points: IPoint[]) => {
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    points.forEach(p => {
        if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x;
        if(p.z < minZ) minZ = p.z; if(p.z > maxZ) maxZ = p.z;
    });
    return { x: (minX + maxX) / 2, z: (minZ + maxZ) / 2 };
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {

    let bestSnap: SnapResult;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;

    if (intersectedObject && shapeData) {
        bestSnap = { 
            position: intersectedObject.point, 
            type: 'face', 
            distance: 0, 
            snapObjectId: shapeData.id 
        };
    } else {
        bestSnap = {
            position: new THREE.Vector3(
                Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
                cursorPos.y, 
                Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
            ),
            type: 'grid',
            distance: Infinity
        };
    }

    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ptVec.distanceTo(cursorPos);
        if (dist < threshold * 1.5) {
            return { position: ptVec, type: 'endpoint', distance: dist };
        }
    }

    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;

        if (shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 for(const ep of endpoints) {
                     if (Math.abs(ep.y - cursorPos.y) < 0.2) {
                         const dist = ep.distanceTo(cursorPos);
                         if (dist < threshold) {
                             if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                                 bestSnap = { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id };
                             }
                         }
                     }
                 }
                 continue; 
             }
        }

        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);

            if (dist < threshold) {
                 if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                    bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
                 }
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold) {
                     if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                        bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                     }
                }
            }
        }
    }

    if (bestSnap.type === 'vertex' || bestSnap.type === 'endpoint') return bestSnap;

    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);

                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }

                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }

    if (bestEdgeSnap) return bestEdgeSnap;

    return bestSnap;
};

// ... Components ...

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);

    useLayoutEffect(() => {
        if (dashed && ref.current) {
            ref.current.computeLineDistances();
        }
    }, [geometry, dashed]);

    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? (
                <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            ) : (
                <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            )}
        </line>
    );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid') return null;

    let color = 'orange';
    if (type === 'midpoint') color = 'cyan';
    else if (type === 'vertex' || type === 'endpoint') color = '#ec4899'; 
    else if (type === 'face') color = '#3b82f6'; 

    return (
        <group position={position}>
            {type === 'face' ? (
                 <mesh rotation={[-Math.PI/2, 0, 0]}>
                    <planeGeometry args={[0.2, 0.2]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} />
                    <lineSegments>
                        <edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} />
                        <lineBasicMaterial color={color} depthTest={false} />
                    </lineSegments>
                 </mesh>
            ) : (
                <mesh>
                    <sphereGeometry args={[type === 'vertex' || type === 'endpoint' ? 0.12 : 0.05]} />
                    <meshBasicMaterial color={color} depthTest={false} />
                </mesh>
            )}

            {type === 'edge' && snapEdge && (
                <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="orange" lineWidth={3} depthTest={false} />
            )}
            {type === 'midpoint' && snapEdge && (
                 <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="cyan" lineWidth={3} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid') return null;

    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none' }}>
            <div className="bg-slate-900/80 text-white text-xs px-2 py-1 rounded backdrop-blur-sm border border-slate-600 whitespace-nowrap flex items-center gap-1">
                {type && <span className={`w-2 h-2 rounded-full ${type === 'grid' ? 'bg-slate-500' : type === 'face' ? 'bg-blue-500' : 'bg-green-500'}`} />}
                {text}
            </div>
        </Html>
    );
};

const ShapeOutline: React.FC<{ shape: IShape; color: string; opacity: number }> = ({ shape, color, opacity }) => {
    const geometry = useMemo(() => {
        const shape2D = createThreeShape(shape.points);
        const geom = new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false });
        return new THREE.EdgesGeometry(geom);
    }, [shape.points, shape.height]);

    return (
        <lineSegments geometry={geometry} rotation={[-Math.PI / 2, 0, 0]}>
            <lineBasicMaterial color={color} transparent opacity={opacity} />
        </lineSegments>
    );
};

const useShapeDrag = (
    shape: IShape,
    isSelected: boolean,
    tool: ToolType,
    updateShape: (id: string, updates: Partial<IShape>) => void,
    setDraggingState: (isDragging: boolean) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({
        start: new THREE.Vector3(),
        offset: new THREE.Vector3(),
        isDragging: false
    });

    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2(
            (clientX / gl.domElement.clientWidth) * 2 - 1,
            -(clientY / gl.domElement.clientHeight) * 2 + 1
        );
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };

    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging || !groupRef.current) return;

        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const newPos = new THREE.Vector3().addVectors(intersect, dragInfo.current.offset);
             newPos.x = Math.round(newPos.x / SNAP_GRID) * SNAP_GRID;
             newPos.z = Math.round(newPos.z / SNAP_GRID) * SNAP_GRID;
             newPos.y = dragInfo.current.start.y;

             groupRef.current.position.copy(newPos);
        }
    }, [camera, gl]);

    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;

        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);

        if (groupRef.current) {
            const finalPos = groupRef.current.position;
            if (finalPos.distanceTo(dragInfo.current.start) > 0.001) {
                updateShape(shape.id, { position: [finalPos.x, finalPos.y, finalPos.z] });
            } else {
                 groupRef.current.position.copy(dragInfo.current.start);
            }
        }
    }, [handlePointerMove, updateShape, shape.id, setDraggingState]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();

        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.start.set(shape.position[0], shape.position[1], shape.position[2]);
            dragInfo.current.offset.subVectors(groupRef.current.position, intersect);

            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, camera, gl, handlePointerMove, handlePointerUp, setDraggingState]);

    useEffect(() => {
        return () => {
             window.removeEventListener('pointermove', handlePointerMove);
             window.removeEventListener('pointerup', handlePointerUp);
        };
    }, [handlePointerMove, handlePointerUp]);

    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers, setDraggingState }: ShapeRendererProps) => {
    const { unit, tool, updateShape } = useApp();
    // REMOVED: hovered state caused re-renders during dragging, leading to visual deformation.

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);

    const { groupRef, handlePointerDown } = useShapeDrag(shape, isSelected, tool, updateShape, setDraggingState);

    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;

    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    if (shape.type === 'dimension') {
         if (shape.points.length < 2) return null;
         const start = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
         const end = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
         const dist = start.distanceTo(end);
         const labelText = unit === 'cm' ? `${(dist * 100).toFixed(1)} cm` : `${dist.toFixed(3)} m`;
         return (
             <group onClick={onSelect} userData={{ isShape: true, id: shape.id, isContainer: true }} name="dimension_group">
                <SimpleLine points={[[start.x, start.y+0.05, start.z], [end.x, end.y+0.05, end.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={2} depthTest={false} />
                <mesh position={[start.x, start.y + 0.05, start.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <mesh position={[end.x, end.y + 0.05, end.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <Html position={[(start.x+end.x)/2, (start.y+end.y)/2 + 0.1, (start.z+end.z)/2]} center>
                    <div className="bg-slate-900/90 text-yellow-400 font-mono text-xs px-2 py-1 rounded border border-yellow-500/50 backdrop-blur-sm pointer-events-none whitespace-nowrap shadow-lg select-none">{labelText}</div>
                </Html>
             </group>
         );
    }

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 

            onPointerDown={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerDown(e);
                } else if (tool === ToolType.SELECT) {
                    if (!isSelected) {
                        onSelect(e);
                    }
                    handlePointerDown(e);
                } else {
                    drawingHandlers.handlePointerDown(e);
                }
            }}
            onPointerMove={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerMove(e);
                }
            }}
            onPointerUp={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerUp();
                } else {
                    drawingHandlers.handlePointerUp(e);
                }
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial 
                    color={highlightColor} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.6 : 1.0} 
                    polygonOffset={shape.type === 'flat'} 
                    polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} 
                />
            </mesh>
            <ShapeOutline shape={shape} color="#333" opacity={isPushPullMode ? 0.2 : 0.5} />
        </group>
    );
});

