const usePushPullManager = () => {
    const { tool, updateShape, shapes, setMeasurement, formatValue } = useApp();
    const { camera, gl } = useThree();
    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0), dragHeight: undefined
    });
    const [tempShape, setTempShapeState] = useState<IShape | null>(null);
    const tempShapeRef = useRef<IShape | null>(null);
    const setTempShape = (s: IShape | null) => { tempShapeRef.current = s; setTempShapeState(s); };
    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = useCallback((e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const intersection = e.intersections.find(i => i.face && (i.object.userData?.isShape || i.object.parent?.userData?.isShape));
        if (!intersection || !intersection.face) return null;
        const object = intersection.object;
        let shapeId: string | null = null;
        if (object.userData?.isShape) shapeId = object.userData.id;
        else if (object.parent?.userData?.isShape) shapeId = object.parent.userData.id;
        if (!shapeId) return null;
        const shape = shapes.find(s => s.id === shapeId);
        if (!shape || shape.type === 'dimension') return null;
        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        if (worldNormal.y > 0.9) return { mode: 'top', hoveredShapeId: shapeId, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, 1, 0) };
        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const invRot = -shape.rotation;
            const xLocal = hitPoint.x * Math.cos(invRot) - hitPoint.z * Math.sin(invRot);
            const zLocal = hitPoint.x * Math.sin(invRot) + hitPoint.z * Math.cos(invRot);
            let closestIndex = -1;
            let minDistSq = Infinity;
            const pts = shape.points;
            for(let i=0; i<pts.length; i++) {
                const p1 = pts[i];
                const p2 = pts[(i+1) % pts.length];
                const unscaledX = xLocal / shape.scale[0];
                const unscaledZ = zLocal / shape.scale[2];
                const d2 = distToSegmentSquared(new THREE.Vector3(unscaledX, 0, unscaledZ), new THREE.Vector3(p1.x, 0, p1.z), new THREE.Vector3(p2.x, 0, p2.z));
                if (d2 < minDistSq) { minDistSq = d2; closestIndex = i; }
            }
            if (closestIndex !== -1) {
                const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize();
                return { mode: 'side', hoveredShapeId: shapeId, hoveredEdgeIndex: closestIndex, normal: flatNormal };
            }
        }
        return null;
    }, [shapes]);

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;
        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;
            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
            if (ppState.mode === 'top') {
                const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint);
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);
                if (target) {
                    const deltaY = target.y - ppState.dragStartPoint.y;
                    const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);
                    setPPState(prev => ({ ...prev, dragHeight: newHeight }));
                    setMeasurement(`高度: ${formatValue(newHeight)}`);
                }
            } else if (ppState.mode === 'side') {
                const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);
                if (target) {
                    const diff = target.clone().sub(ppState.dragStartPoint);
                    const projection = diff.dot(ppState.normal);
                    const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection);

                    // Display offset
                    setMeasurement(`偏移: ${formatValue(projection)}`);

                    const rot = -shape.rotation;
                    const dx = moveVectorWorld.x * Math.cos(rot) - moveVectorWorld.z * Math.sin(rot);
                    const dz = moveVectorWorld.x * Math.sin(rot) + moveVectorWorld.z * Math.cos(rot);
                    const dLocalX = dx / shape.scale[0];
                    const dLocalZ = dz / shape.scale[2];
                    const idx = ppState.hoveredEdgeIndex;
                    const newPoints = ppState.originalPoints.map(p => ({...p}));
                    const p1 = newPoints[idx];
                    const p2 = newPoints[(idx+1) % newPoints.length];
                    p1.x += dLocalX; p1.z += dLocalZ;
                    p2.x += dLocalX; p2.z += dLocalZ;
                    const updatedShape = { ...shape, points: newPoints };
                    setTempShape(updatedShape);
                }
            }
        } else {
            const res = identifyFace(e);
            if (res) {
                e.stopPropagation();
                document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize';
                setPPState(prev => ({ ...prev, mode: res.mode!, hoveredShapeId: res.hoveredShapeId!, hoveredEdgeIndex: res.hoveredEdgeIndex!, normal: res.normal! }));
            } else {
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        }
    };
    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();
        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;
             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') {
                 const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), e.point);
                 raycaster.ray.intersectPlane(plane, startPoint);
             } else {
                 const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
                 raycaster.ray.intersectPlane(plane, startPoint);
             }
             setPPState(prev => ({ ...prev, dragStartPoint: startPoint, originalHeight: shape.height, dragHeight: shape.height, originalPoints: JSON.parse(JSON.stringify(shape.points)) }));
             if (ppState.mode === 'side') setTempShape(shape);
        }
    };
    const handlePointerUp = useCallback(() => {
        if (ppState.mode === 'top' && ppState.dragHeight !== undefined && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             const updates: Partial<IShape> = { height: ppState.dragHeight };
             if (shape && shape.type === 'flat' && ppState.dragHeight > 0.05) {
                updates.type = 'solid';
                if (shape.color === FLAT_COLOR) updates.color = DEFAULT_COLOR;
             }
             updateShape(ppState.hoveredShapeId, updates);
        } else if (tempShapeRef.current) {
            updateShape(tempShapeRef.current.id, { points: tempShapeRef.current.points });
        }
        setTempShape(null);
        setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [], dragHeight: undefined }));
        setMeasurement('');
    }, [updateShape, ppState.mode, ppState.dragHeight, ppState.hoveredShapeId, shapes, setMeasurement]);
    useEffect(() => {
        if (isDragging) {
            const onGlobalPointerUp = () => handlePointerUp();
            window.addEventListener('pointerup', onGlobalPointerUp);
            return () => window.removeEventListener('pointerup', onGlobalPointerUp);
        }
    }, [isDragging, handlePointerUp]);
    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging, tempShape };
};

const useDrawingManager = () => {
    // (Same as before + Fragment logic integration from turn 2)
    const { tool, addShape, shapes, wallThickness, setTool, replaceShapes, updateShape, setMeasurement } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [drawingHeight, setDrawingHeight] = useState(0);
    const [typedInput, setTypedInput] = useState('');

    useEffect(() => {
        setDrawPoints([]);
        setSnapInfo(null);
        setIsDragging(false);
        setDrawingHeight(0);
        setMeasurement(''); // Clear measurement on tool change
        setTypedInput('');
    }, [tool, setMeasurement]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        let shapeCreated = false;
        const baseHeight = finalPoints.length > 0 ? finalPoints[0].y : 0;

        // ... (Rect, Circle, Arc logic)
        if (tool === ToolType.DRAW_RECT && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1]; 
             const width = Math.abs(end.x - start.x);
             const depth = Math.abs(end.z - start.z);
             if (width >= 0.01 && depth >= 0.01) {
                 const cx = (start.x + end.x) / 2;
                 const cz = (start.z + end.z) / 2;
                 const halfW = width / 2;
                 const halfD = depth / 2;
                 const points: IPoint[] = [{ x: -halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: -halfD }];
                 addShape({ id: `rect-${Date.now()}`, type: 'flat', name: 'Room/Floor', points, height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [cx, 0, cz], rotation: 0, scale: [1, 1, 1] });
                 shapeCreated = true;
             }
        } else if (tool === ToolType.DRAW_CIRCLE && finalPoints.length >= 2) {
            const start = finalPoints[0];
            const end = finalPoints[1];
            const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
            if (radius > 0.01) {
                const points = createCirclePoints(radius);
                addShape({ id: `circle-${Date.now()}`, type: 'flat', name: 'Circle', points, height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [start.x, 0, start.z], rotation: 0, scale: [1, 1, 1] });
                shapeCreated = true;
            }
        } else if (tool === ToolType.DRAW_ARC && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[1];
             const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
             if (radius > 0.01) {
                 const points = createCirclePoints(radius); 
                 addShape({ id: `arc-${Date.now()}`, type: 'flat', name: 'Arc', points, height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [start.x, 0, start.z], rotation: 0, scale: [1, 1, 1] });
                 shapeCreated = true;
             }
        } else if (tool === ToolType.MEASURE && finalPoints.length >= 2) {
            const start = finalPoints[0];
            const end = finalPoints[1];
            const dist = new THREE.Vector3(start.x, start.y, start.z).distanceTo(new THREE.Vector3(end.x, end.y, end.z));

            if (dist > 0.01) {
                const midX = (start.x + end.x) / 2;
                const midY = (start.y + end.y) / 2;
                const midZ = (start.z + end.z) / 2;
                const localStart = { x: start.x - midX, y: start.y - midY, z: start.z - midZ };
                const localEnd = { x: end.x - midX, y: end.y - midY, z: end.z - midZ };

                addShape({ 
                    id: `dim-${Date.now()}`, 
                    type: 'dimension', 
                    name: 'Dimension', 
                    points: [localStart, localEnd], 
                    height: 0, 
                    color: DIMENSION_COLOR, 
                    position: [midX, midY, midZ], 
                    rotation: 0, 
                    scale: [1, 1, 1] 
                });
                shapeCreated = true;
            }
        } else if (tool === ToolType.DRAW_LINE && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1]; 
             const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);

             if (dist >= 0.01) {
                const idsToRemove = new Set<string>();
                const shapesToAddList: IShape[] = [];

                // 1. Edge Fragmentation (Planar Graph for Lines)
                const existingEdges: {start: IPoint, end: IPoint, originalId: string}[] = [];
                shapes.forEach(shape => {
                    if (shape.name === 'Edge') {
                        const eps = getLineEndpoints(shape);
                        if (eps) {
                            existingEdges.push({ start: {x: eps[0].x, y: 0, z: eps[0].z}, end: {x: eps[1].x, y: 0, z: eps[1].z}, originalId: shape.id });
                            idsToRemove.add(shape.id); 
                        }
                    }
                });

                const allSegments = existingEdges.map(e => ({ start: e.start, end: e.end }));
                allSegments.push({ start: {x: start.x, y: 0, z: start.z}, end: {x: end.x, y: 0, z: end.z} });

                const fragmented = fragmentSegments(allSegments);
                const cycles = findClosedCycles(fragmented);

                fragmented.forEach(seg => {
                     const dx = seg.end.x - seg.start.x;
                     const dz = seg.end.z - seg.start.z;
                     const len = Math.sqrt(dx*dx + dz*dz);
                     const angle = Math.atan2(dz, dx);
                     const cx = (seg.start.x + seg.end.x) / 2;
                     const cz = (seg.start.z + seg.end.z) / 2;
                     const thickness = 0.02; 
                     const halfL = len / 2;
                     const halfW = thickness / 2;
                     const points = [ { x: -halfL, y: 0, z: -halfW }, { x: halfL, y: 0, z: -halfW }, { x: halfL, y: 0, z: halfW }, { x: -halfL, y: 0, z: halfW } ];
                     shapesToAddList.push({ id: `edge-${Date.now()}-${Math.random()}`, type: 'flat', name: 'Edge', points, height: 0.005, color: '#334155', position: [cx, baseHeight, cz], rotation: -angle, scale: [1, 1, 1] });
                });

                cycles.forEach(cycle => {
                    const center = getBoundingCenter(cycle);
                    const centeredPoints = cycle.map(p => ({ x: p.x - center.x, y: 0, z: p.z - center.z }));
                    shapesToAddList.push({ id: `floor-${Date.now()}-${Math.random()}`, type: 'flat', name: 'Floor', points: centeredPoints, height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [center.x, baseHeight, center.z], rotation: 0, scale: [1, 1, 1] });
                });

                // 2. Face Splitting Logic (Cutting Polygons)
                shapes.forEach(shape => {
                    if ((shape.type === 'flat' || shape.type === 'solid') && shape.name !== 'Edge' && shape.points.length > 2) {

                        // Transform points to world space for intersection calculation
                        const worldPoints = shape.points.map(p => {
                            const vec = transformPoint(p, shape);
                            return { x: vec.x, y: vec.y, z: vec.z };
                        });

                        const splitResult = splitPolygonByLine(worldPoints, start, end);

                        if (splitResult) {
                            const [poly1Points, poly2Points] = splitResult;
                            idsToRemove.add(shape.id);

                            [poly1Points, poly2Points].forEach(newPoints => {
                                // Calculate new center for the split piece
                                const center = getBoundingCenter(newPoints);

                                // Relativize points to the new center. 
                                // Since we calculated intersections in world space, we must reset rotation to 0 for simplicity.
                                const localPoints = newPoints.map(p => ({
                                    x: p.x - center.x,
                                    y: 0,
                                    z: p.z - center.z
                                }));

                                shapesToAddList.push({
                                    ...shape,
                                    id: `split-${Date.now()}-${Math.random()}`,
                                    points: localPoints,
                                    position: [center.x, shape.position[1], center.z],
                                    rotation: 0, // Reset rotation as points are now baked in world orientation relative to new center
                                    scale: [1, 1, 1] // Reset scale
                                });
                            });
                        }
                    }
                });

                if (idsToRemove.size > 0 || shapesToAddList.length > 0) {
                     replaceShapes(Array.from(idsToRemove), shapesToAddList);
                }
                shapeCreated = true;
             }
        }

        if (shapeCreated) {
            setDrawPoints([]);
            if (tool !== ToolType.MEASURE) {
                 setTool(ToolType.SELECT); 
            }
            setMeasurement('');
            setTypedInput('');
        }
    }, [tool, addShape, wallThickness, setTool, replaceShapes, updateShape, shapes, setMeasurement]);

    // Handle Manual Input Submit (Enter key)
    const handleInputSubmit = useCallback(() => {
        if (!typedInput || drawPoints.length === 0) return;

        const start = drawPoints[drawPoints.length - 1];
        const startVec = new THREE.Vector3(start.x, start.y, start.z);
        const cursorVec = cursorPos.clone();

        let targetVec = new THREE.Vector3();
        const direction = cursorVec.clone().sub(startVec).normalize();

        // Handling for different tools
        if (tool === ToolType.DRAW_RECT) {
             const parts = typedInput.split(/[, ]+/).filter(p => p.trim() !== '').map(parseFloat);
             if (parts.length > 0 && !parts.some(isNaN)) {
                 const w = parts[0];
                 const d = parts.length > 1 ? parts[1] : w;

                 const dx = cursorVec.x - startVec.x;
                 const dz = cursorVec.z - startVec.z;
                 const signX = dx >= 0 ? 1 : -1;
                 const signZ = dz >= 0 ? 1 : -1;

                 targetVec.set(startVec.x + signX * w, startVec.y, startVec.z + signZ * d);
             } else {
                 return;
             }
        } else {
             // Line, Circle, Arc, Measure: Single value length/radius
             const val = parseFloat(typedInput);
             if (isNaN(val)) return;

             // If cursor is at start (no direction), use default X? No, wait for cursor move.
             // If direction length is 0, default to X axis
             if (cursorVec.distanceTo(startVec) < 0.001) {
                 direction.set(1, 0, 0);
             }

             targetVec = startVec.clone().add(direction.multiplyScalar(val));
        }

        const finalPoints = [...drawPoints, { x: targetVec.x, y: targetVec.y, z: targetVec.z }];
        finishShape(finalPoints);

    }, [typedInput, drawPoints, cursorPos, tool, finishShape]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        if (e.button !== 0) return;
        e.stopPropagation();
        setIsDragging(true);
        setTypedInput(''); // Clear input on click

        // CRITICAL FIX: Sync cursor pos to ensure preview starts at click point
        // This prevents the "Drawing Preview" from using a default (0,0,0) coordinate momentarily.
        setCursorPos(e.point.clone());

        const pt = e.point.clone();

        if (drawPoints.length === 0) {
            setDrawPoints([{ x: pt.x, y: pt.y, z: pt.z }]);
            if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.MEASURE) {
                 setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
            }
        } else {
            if (tool === ToolType.DRAW_LINE) {
                setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
            }
        }
    }, [tool, drawPoints]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        setIsDragging(false);

        if ((tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.MEASURE || tool === ToolType.DRAW_LINE) && drawPoints.length >= 2) {
             const current = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z };
             const points = [...drawPoints];
             points[points.length-1] = current;
             finishShape(points);
        }
    }, [tool, drawPoints, cursorPos, finishShape]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
    }, []);

    // Global Key Listener for Input
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
             // If not drawing, ignore numbers (unless we want to support typing dimension for selected object later)
             if ([ToolType.SELECT, ToolType.PUSH_PULL].includes(tool)) return;
             if (drawPoints.length === 0) return; // Need at least a start point

             if (e.key === 'Enter') {
                 handleInputSubmit();
                 return;
             }
             if (e.key === 'Backspace') {
                 setTypedInput(prev => prev.slice(0, -1));
                 return;
             }

             // Allow numbers, dot, comma, minus
             if (/^[0-9.,-]$/.test(e.key)) {
                 setTypedInput(prev => prev + e.key);
             }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, drawPoints, handleInputSubmit]);

    return { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging, drawingHeight, handlePointerDown, handlePointerUp, handleClick, typedInput };
};

const EditorScene: React.FC<{ view: string | null; onViewFinished: () => void }> = ({ view, onViewFinished }) => {
    const { shapes, selectedIds, selectShape, tool } = useApp();
    const { ppState, handlePointerMove, handlePointerDown: ppDown, handlePointerUp: ppUp, tempShape, isDragging: isPPDragging } = usePushPullManager();
    const { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging: isDrawing, drawingHeight, handlePointerDown: drawDown, handlePointerUp: drawUp, handleClick, typedInput } = useDrawingManager();
    const [isObjectDragging, setIsObjectDragging] = useState(false);

    const renderShapes = useMemo(() => {
        if (tempShape && ppState.hoveredShapeId) {
            return shapes.map(s => s.id === ppState.hoveredShapeId ? tempShape : s);
        }
        return shapes;
    }, [shapes, tempShape, ppState.hoveredShapeId]);

    const raycaster = useThree((state) => state.raycaster);
    useEffect(() => {
        raycaster.params.Line.threshold = 0.2;
    }, [raycaster]);

    const pushPullHandlers = useMemo(() => ({ handlePointerDown: ppDown, handlePointerUp: ppUp, handlePointerMove: handlePointerMove }), [ppDown, ppUp, handlePointerMove]);
    const drawingHandlers = useMemo(() => ({ handlePointerDown: drawDown, handlePointerUp: drawUp, handleClick: handleClick }), [drawDown, drawUp, handleClick]);

    return (
        <>
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 5]} intensity={1} castShadow shadow-mapSize={[2048, 2048]}>
                <orthographicCamera attach="shadow-camera" left={-20} right={20} top={20} bottom={-20} />
            </directionalLight>

            <Grid position={[0, -0.01, 0]} args={[40, 40]} cellSize={1} cellThickness={1} cellColor="#e2e8f0" sectionSize={5} sectionThickness={1.5} sectionColor="#cbd5e1" fadeDistance={50} infiniteGrid />

            <group 
                onPointerDown={(e) => {
                    if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) drawDown(e);
                    else selectShape('', false); 
                }} 
                onPointerUp={(e) => {
                         if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) drawUp(e);
                }}
                onPointerMove={(e) => {
                         if (tool === ToolType.PUSH_PULL) handlePointerMove(e);
                }}
            >
                <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow>
                    <planeGeometry args={[100, 100]} />
                    <meshBasicMaterial visible={false} /> 
                </mesh>
            </group>

            {renderShapes.map(shape => (
                <ShapeRenderer 
                    key={shape.id} 
                    shape={shape} 
                    isSelected={selectedIds.includes(shape.id)} 
                    onSelect={(e) => {
                        selectShape(shape.id, e.shiftKey || (tool === ToolType.SELECT && selectedIds.length > 0 && e.metaKey)); 
                    }}
                    pushPullState={ppState}
                    pushPullHandlers={pushPullHandlers}
                    drawingHandlers={drawingHandlers}
                    setDraggingState={setIsObjectDragging}
                />
            ))}

            <InteractionLayer shapes={shapes} tool={tool} setCursorPos={setCursorPos} setSnapInfo={setSnapInfo} cursorPos={cursorPos} snapInfo={snapInfo} drawPoints={drawPoints} isDragging={isDrawing} drawingHeight={drawingHeight} typedInput={typedInput} />

            <SelectionGizmo />

            <OrbitControls makeDefault minDistance={2} maxDistance={50} dampingFactor={0.1} enabled={!isDrawing && !isPPDragging && !isObjectDragging} />
            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="black" />
            </GizmoHelper>
            <CameraHandler view={view} onFinished={onViewFinished} />
        </>
    );
};

