import { Vector3 } from 'three';

export enum ToolType {
  SELECT = 'SELECT',
  PUSH_PULL = 'PUSH_PULL', // 推拉工具 (調整長寬高)
  DRAW_LINE = 'DRAW_LINE', // 直線
  DRAW_RECT = 'DRAW_RECT', // 矩形
  DRAW_CIRCLE = 'DRAW_CIRCLE', // 圓形
  DRAW_ARC = 'DRAW_ARC', // 弧形 (門)
}

export type ShapeType = 'solid' | 'flat'; // 立體 | 平面

export type TransformMode = 'translate' | 'scale'; // 移動或縮放

export interface IPoint {
  x: number;
  y: number;
  z: number;
}

export interface IShape {
  id: string;
  groupId?: string; // ID for grouping multiple objects
  type: ShapeType;
  points: IPoint[]; // 地面上的 2D 輪廓點
  height: number;
  color: string;
  position: [number, number, number];
  rotation: number; // Y 軸旋轉 (弧度)
  scale: [number, number, number]; // 新增縮放比例
  name: string;
}

export interface ISceneState {
  shapes: IShape[];
  selectedId: string | null;
  tool: ToolType;
  gridSize: number;
}

// AI Generation Types
export interface AIGeneratedItem {
  name: string;
  width: number;
  depth: number;
  height: number;
  color: string;
  x: number;
  z: number;
}

