                className={`flex-1 text-xs py-1 rounded transition-colors ${unit === 'cm' ? 'bg-slate-700 text-white' : 'text-slate-500 hover:text-slate-300'}`}
            >
                公分
            </button>
        </div>
      </div>
    </div>
  );
};

